// Tags for Policy Dispatch
struct Fast {};
struct Safe {};

// Compile-Time Polymorphic Overloads
constexpr int execute(int x, Fast) { return x * 2; }
constexpr int execute(int x, Safe) { return x + 1; }

// Template Metaprogramming Dispatcher (Policy Selection)
template <bool UseFast> struct Policy { using Tag = Safe; };
template <> struct Policy<true> { using Tag = Fast; };

// High-Level Interface
template <bool UseFast>
constexpr int calculate(int x) {
    using T = typename Policy<UseFast>::Tag;
    return execute(x, T{}); // Compile-time function selection
}

constexpr int A = calculate<true>(5);  // Evaluated at compile time (10)
constexpr int B = calculate<false>(5); // Evaluated at compile time (6)
